ompany_address_kanji_country" VARCHAR, "company_address_kanji_line_1" VARCHAR, "company_address_kanji_line_2" VARCHAR, "company_address_kanji_postal_code" VARCHAR, "company_address_kanji_state" VARCHAR, "company_address_kanji_town" VARCHAR, "company_address_line_1" VARCHAR, "company_address_line_2" VARCHAR, "company_address_postal_code" VARCHAR, "company_address_state" VARCHAR, "company_directors_provided" VARCHAR, "company_executives_provided" VARCHAR, "company_name" VARCHAR, "company_name_kana" VARCHAR, "company_name_kanji" VARCHAR, "company_owners_provided" VARCHAR, "company_phone" VARCHAR, "company_structure" VARCHAR, "company_tax_id_provided" VARCHAR, "company_tax_id_registrar" VARCHAR, "company_vat_id_provided" VARCHAR, "company_verification_document_back" VARCHAR, "company_verification_document_details" VARCHAR, "company_verification_document_details_code" VARCHAR, "company_verification_document_front" VARCHAR, "country" VARCHAR, "created" VARCHAR, "default_currency" VARCHAR, "details_submitted" BOOLEAN, "email" VARCHAR, "individual_id" VARCHAR, "is_deleted" BOOLEAN, "metadata" VARCHAR, "payouts_enabled" BOOLEAN, "requirements_current_deadline" VARCHAR, "requirements_currently_due" VARCHAR, "requirements_disabled_reason" VARCHAR, "requirements_errors" VARCHAR, "requirements_eventually_due" VARCHAR, "requirements_past_due" VARCHAR, "requirements_pending_verification" VARCHAR, "settings_branding_icon" VARCHAR, "settings_branding_logo" VARCHAR, "settings_branding_primary_color" VARCHAR, "settings_card_payments_decline_on_avs_failure" VARCHAR, "settings_card_payments_decline_on_cvc_failure" VARCHAR, "settings_card_payments_statement_descriptor_prefix" VARCHAR, "settings_dashboard_display_name" VARCHAR, "settings_dashboard_timezone" VARCHAR, "settings_payments_statement_descriptor" VARCHAR, "settings_payments_statement_descriptor_kana" VARCHAR, "settings_payments_statement_descriptor_kanji" VARCHAR, "settings_payouts_debit_negative_balances" BOOLEAN, "settings_payouts_schedule_delay_days" BIGINT, "settings_payouts_schedule_interval" VARCHAR, "settings_payouts_schedule_monthly_anchor" VARCHAR, "settings_payouts_schedule_weekly_anchor" VARCHAR, "settings_payouts_statement_descriptor" VARCHAR, "tos_acceptance_date" VARCHAR, "tos_acceptance_ip" VARCHAR, "tos_acceptance_user_agent" VARCHAR, "type" VARCHAR);
